# Generated by manage.py generate_test_cases.
"""Exercise attendance identity, independent responses, and duplicate prevention."""

from typing import Any

from django.core.exceptions import ValidationError
from django.utils import timezone

from bloomerp.models.communication.calendar import (
    CalendarEvent,
    CalendarEventParticipant,
)
from bloomerp.tests.base import (
    BloomerpModelTestCase,
    ExpectedModelException,
    ModelScenario,
)

from .fixtures import CalendarFixtures


class TestCalendarEventParticipantModel(CalendarFixtures, BloomerpModelTestCase):
    model = CalendarEventParticipant

    def get_test_scenarios(self) -> list[ModelScenario[CalendarEventParticipant]]:
        """Cover external invitations, internal identities, and response updates."""
        return [
            ModelScenario(
                name="Reply updates the invited internal participant without copying event",
                preparation=self.prepare_participants,
                create_args=self.internal_args,
                update_args={
                    "response_status": "accepted",
                    "responded_at": timezone.now(),
                },
                update_validators=self.has_independent_response,
            ),
            ModelScenario(
                name="User-only invitation needs no email",
                preparation=self.prepare_participants,
                create_args=self.user_only_args,
                create_validators=self.is_awaiting,
            ),
            ModelScenario(
                name="External invitation awaits response",
                preparation=self.prepare_participants,
                create_args=self.external_args,
                create_validators=self.is_awaiting,
            ),
            ModelScenario(
                name="Neither user nor email is invalid",
                preparation=self.prepare_participants,
                create_args=self.anonymous_args,
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            ),
            ModelScenario(
                name="Same invited email cannot create another attendee",
                preparation=self.prepare_participants,
                create_args=self.duplicate_email,
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            ),
            ModelScenario(
                name="Same user cannot create another attendee with another email",
                preparation=self.prepare_participants,
                create_args=self.duplicate_user,
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            ),
        ]

    def prepare_participants(self) -> None:
        """Create a shared meeting with one external participant."""
        self.prepare()
        self.event = CalendarEvent.objects.create(**self.event_args())
        self.other = CalendarEventParticipant.objects.create(
            event=self.event, email="other@example.com"
        )

    def internal_args(self) -> dict[str, Any]:
        """Invite a user with the email used for the same scheduling invitation."""
        return {"event": self.event, "user": self.user, "email": "internal@example.com"}

    def user_only_args(self) -> dict[str, Any]:
        """Invite an internal user using only their user identity."""
        return {"event": self.event, "user": self.user}

    def external_args(self) -> dict[str, Any]:
        """Invite an external email without linking an internal user."""
        return {"event": self.event, "email": "visitor@example.com"}

    def anonymous_args(self) -> dict[str, Any]:
        """Attempt an attendee with no usable identity."""
        return {"event": self.event}

    def duplicate_email(self) -> dict[str, Any]:
        """Attempt the same invited email with different capitalization."""
        return {"event": self.event, "email": "OTHER@example.com"}

    def duplicate_user(self) -> dict[str, Any]:
        """Attempt to invite the same user twice with different email identities."""
        CalendarEventParticipant.objects.create(**self.internal_args())
        return {
            "event": self.event,
            "user": self.user,
            "email": "alternate@example.com",
        }

    def is_awaiting(self, participant: CalendarEventParticipant) -> bool:
        """Confirm invitations alone do not imply acceptance."""
        return (
            participant.response_status == "awaiting_response"
            and participant.responded_at is None
        )

    def has_independent_response(self, participant: CalendarEventParticipant) -> bool:
        """Confirm one response leaves the other attendee and placement untouched."""
        self.other.refresh_from_db()
        return (
            participant.response_status == "accepted"
            and participant.responded_at is not None
            and self.other.response_status == "awaiting_response"
            and self.event.participants.count() == 2
            and not self.event.inboxes.exists()
        )
